import{_ as s}from"./plugin-vue_export-helper-c27b6911.js";import{o as a,c as n,e}from"./app-09e0be14.js";const t={},o=e(`<h1 id="ripgrep-超高速代码-文本搜索工具" tabindex="-1"><a class="header-anchor" href="#ripgrep-超高速代码-文本搜索工具" aria-hidden="true">#</a> ripgrep（超高速代码/文本搜索工具）</h1><blockquote><p>Homebrew 版本 15.1.0 ｜ 主页：见官方文档 ｜ 安装：<code>brew install ripgrep</code></p></blockquote><h2 id="一、它是什么" tabindex="-1"><a class="header-anchor" href="#一、它是什么" aria-hidden="true">#</a> 一、它是什么</h2><p>ripgrep（命令行名 <code>rg</code>）是一个基于 Rust 编写、以<strong>极快</strong>著称的递归正则搜索工具，专门用来在文件树中按内容搜索文本。它利用 Rust 的并行执行和 SIMD 指令集，比 grep、ack、ag 快数倍到数十倍，同时<strong>默认遵守 <code>.gitignore</code></strong>，不会把无关的构建产物、二进制和隐藏文件扫进来。典型应用场景包括：在大型代码仓库里快速定位函数定义与调用、查找 TODO 或某个字符串出现在哪些文件、配合 IDE 或脚本做批量替换前的&quot;找到所有出现位置&quot;。</p><h2 id="二、安装与升级" tabindex="-1"><a class="header-anchor" href="#二、安装与升级" aria-hidden="true">#</a> 二、安装与升级</h2><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安装</span>
brew <span class="token function">install</span> ripgrep

<span class="token comment"># 升级</span>
brew upgrade ripgrep

<span class="token comment"># 卸载</span>
brew uninstall ripgrep

<span class="token comment"># 验证安装成功（查看版本）</span>
rg <span class="token parameter variable">--version</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>安装后 <code>rg</code> 即进入 PATH，直接可全局调用。如果之前用 <code>cargo install</code> 或源码编译过旧版本，建议先卸载旧版再 <code>brew install</code> 以免冲突。</p><h2 id="三、常用命令速查" tabindex="-1"><a class="header-anchor" href="#三、常用命令速查" aria-hidden="true">#</a> 三、常用命令速查</h2><table><thead><tr><th>命令</th><th>参数说明</th><th>示例</th></tr></thead><tbody><tr><td><code>rg pattern [路径]</code></td><td>在路径（默认当前目录）中递归搜索匹配 pattern 的行</td><td><code>rg &quot;fn main&quot;</code></td></tr><tr><td><code>-i</code> / <code>--ignore-case</code></td><td>忽略大小写搜索</td><td><code>rg -i &quot;todo&quot; src/</code></td></tr><tr><td><code>-w</code> / <code>--word-regexp</code></td><td>只匹配完整单词</td><td><code>rg -w &quot;fix&quot;</code></td></tr><tr><td><code>-l</code> / <code>--files-with-matches</code></td><td>只列出包含匹配的文件名</td><td><code>rg -l &quot;import&quot; app/</code></td></tr><tr><td><code>-c</code> / <code>--count</code></td><td>统计每个文件的匹配行数</td><td><code>rg -c &quot;error&quot; --glob &#39;*.log&#39;</code></td></tr><tr><td><code>-n</code> / <code>--line-number</code></td><td>显示匹配行号（默认已开启）</td><td><code>rg -n &quot;password&quot;</code></td></tr><tr><td><code>-A n</code> / <code>-B n</code></td><td>输出匹配行后 n 行 / 前 n 行上下文</td><td><code>rg -A 3 &quot;func&quot; main.go</code></td></tr><tr><td><code>-g</code> / <code>--glob</code></td><td>按文件名模式过滤（可多个）</td><td><code>rg &quot;debug&quot; -g &#39;*.rs&#39; -g &#39;!test_*&#39;</code></td></tr><tr><td><code>-t</code> / <code>--type</code></td><td>按文件类型过滤（如 rs、py、js）</td><td><code>rg &quot;log&quot; -t py</code></td></tr><tr><td><code>-uu</code> / <code>--no-ignore</code></td><td>忽略 .gitignore 等规则全量搜索</td><td><code>rg -uu &quot;secret&quot; .</code></td></tr></tbody></table><h2 id="四、实际示例" tabindex="-1"><a class="header-anchor" href="#四、实际示例" aria-hidden="true">#</a> 四、实际示例</h2><h3 id="示例-1-在项目里找函数定义与调用位置" tabindex="-1"><a class="header-anchor" href="#示例-1-在项目里找函数定义与调用位置" aria-hidden="true">#</a> 示例 1：在项目里找函数定义与调用位置</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 准备：进入一个 Rust 项目目录</span>
<span class="token builtin class-name">cd</span> ~/my-rs-project

<span class="token comment"># 搜索名为 &quot;handle_request&quot; 的所有出现位置（含行号）</span>
rg <span class="token string">&quot;handle_request&quot;</span>

<span class="token comment"># 只看定义（用正则锚定声明）</span>
rg <span class="token string">&quot;^\\s*(pub\\s+)?fn handle_request&quot;</span>

<span class="token comment"># 只列出命中文件，适合快速概览</span>
rg <span class="token parameter variable">-l</span> <span class="token string">&quot;handle_request&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>输出形如：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>src/server.rs:42:    fn handle_request(req: Request) -&gt; Response {
src/handler.rs:17:    handle_request(req);
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-2-跨多种语言查找字符串并统计" tabindex="-1"><a class="header-anchor" href="#示例-2-跨多种语言查找字符串并统计" aria-hidden="true">#</a> 示例 2：跨多种语言查找字符串并统计</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 准备：在某个多语言仓库的根目录</span>
<span class="token builtin class-name">cd</span> ~/repo

<span class="token comment"># 忽略大小写、统计每个文件里 &quot;api_key&quot; 出现几行</span>
rg <span class="token parameter variable">-ic</span> <span class="token string">&quot;api_key&quot;</span> <span class="token parameter variable">--glob</span> <span class="token string">&#39;!*.min.js&#39;</span>

<span class="token comment"># 只想看 Python 和 Go 文件，且附带上下文</span>
rg <span class="token parameter variable">-A</span> <span class="token number">2</span> <span class="token parameter variable">-B</span> <span class="token number">2</span> <span class="token string">&quot;api_key&quot;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;*.py&#39;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;*.go&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-3-全量扫描-忽略-gitignore-排查敏感信息" tabindex="-1"><a class="header-anchor" href="#示例-3-全量扫描-忽略-gitignore-排查敏感信息" aria-hidden="true">#</a> 示例 3：全量扫描（忽略 .gitignore）排查敏感信息</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 准备：进入任意目录</span>
<span class="token builtin class-name">cd</span> ~/work

<span class="token comment"># 强制搜索被忽略的隐藏文件（-uu = 忽略所有忽略规则）</span>
rg <span class="token parameter variable">-uu</span> <span class="token string">&quot;BEGIN PRIVATE KEY&quot;</span> <span class="token builtin class-name">.</span>

<span class="token comment"># 配合 --hidden 显式包含隐藏文件</span>
rg <span class="token parameter variable">--hidden</span> <span class="token string">&quot;password\\s*=&quot;</span> ~/config
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-4-与-find-xargs-联动做批量操作" tabindex="-1"><a class="header-anchor" href="#示例-4-与-find-xargs-联动做批量操作" aria-hidden="true">#</a> 示例 4：与 find/xargs 联动做批量操作</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 找到所有含 &quot;TODO&quot; 的 .ts 文件，逐一交给编辑器打开</span>
rg <span class="token parameter variable">-l</span> <span class="token string">&quot;TODO&quot;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;*.ts&#39;</span> <span class="token operator">|</span> <span class="token function">xargs</span> code

<span class="token comment"># 统计命中文件总数</span>
rg <span class="token parameter variable">-l</span> <span class="token string">&quot;TODO&quot;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;*.ts&#39;</span> <span class="token operator">|</span> <span class="token function">wc</span> <span class="token parameter variable">-l</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="五、进阶技巧与配置" tabindex="-1"><a class="header-anchor" href="#五、进阶技巧与配置" aria-hidden="true">#</a> 五、进阶技巧与配置</h2><p><strong>1. 用别名简化常用组合</strong></p><p>在 shell 配置（<code>~/.zshrc</code> 或 <code>~/.bashrc</code>）里加：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token builtin class-name">alias</span> <span class="token assign-left variable">rgw</span><span class="token operator">=</span><span class="token string">&#39;rg -w&#39;</span>          <span class="token comment"># 全词匹配</span>
<span class="token builtin class-name">alias</span> <span class="token assign-left variable">rgs</span><span class="token operator">=</span><span class="token string">&#39;rg -i&#39;</span>          <span class="token comment"># 忽略大小写</span>
<span class="token builtin class-name">alias</span> <span class="token assign-left variable">rgl</span><span class="token operator">=</span><span class="token string">&#39;rg -l&#39;</span>          <span class="token comment"># 只列文件名</span>
<span class="token builtin class-name">alias</span> <span class="token assign-left variable">rgc</span><span class="token operator">=</span><span class="token string">&#39;rg --color=always&#39;</span>   <span class="token comment"># 强制彩色输出</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>2. 配合 fzf 做模糊搜索跳转</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 先查命中文件，再用 fzf 选择并打开</span>
rg <span class="token parameter variable">-l</span> <span class="token string">&quot;error&quot;</span> <span class="token parameter variable">--glob</span> <span class="token string">&#39;*.js&#39;</span> <span class="token operator">|</span> fzf <span class="token operator">|</span> <span class="token function">xargs</span> code
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>3. 自定义默认忽略与文件类型</strong></p><p>在任意目录放 <code>.ignore</code> 文件（比 .gitignore 优先且全局生效）：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code># .ignore
build/
node_modules/
*.lock
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>还可以在 <code>~/.config/ripgrep/rc</code> 里写全局默认参数，例如：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>--smart-case
--glob &quot;!*.min.js&quot;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>4. 性能提示</strong></p><ul><li>优先用 <code>-t</code> 指定文件类型、<code>-g</code> 限定 glob，能大幅减少扫描量。</li><li>只搜代码时<strong>不必</strong>用 <code>-uu</code>，遵守忽略规则正是 ripgrep 快的原因。</li><li>结合 <code>--stats</code> 查看搜索统计，判断是否扫了过多文件：</li></ul><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>rg <span class="token string">&quot;foo&quot;</span> <span class="token parameter variable">-t</span> rs <span class="token parameter variable">--stats</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="深入-配置文件-config-ripgrep-rc" tabindex="-1"><a class="header-anchor" href="#深入-配置文件-config-ripgrep-rc" aria-hidden="true">#</a> 深入：配置文件（<code>~/.config/ripgrep/rc</code>）</h3><p>ripgrep 会在每次运行时<strong>自动加载</strong> <code>$RIPGREP_CONFIG_PATH</code> 指向的文件；若该变量未设置，则回退到 <code>~/.config/ripgrep/rc</code>（macOS 上即 <code>$XDG_CONFIG_HOME/ripgrep/rc</code>）。该文件里每行写一个<strong>命令行参数</strong>（可带值，支持引号与 <code>#</code> 注释），相当于每次调用都隐式拼在参数前面。</p><p>一个实用的完整配置示例：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code># ~/.config/ripgrep/rc
--smart-case                # 全小写查询自动忽略大小写
--hidden                    # 默认也搜隐藏文件（谨慎，扫 .git 等会变慢）
--glob &quot;!.git/*&quot;            # 但排除 .git 内部
--glob &quot;!node_modules/*&quot;    # 排除依赖目录
--glob &quot;!dist/*&quot;
--glob &quot;!build/*&quot;
--glob &quot;!target/*&quot;
--glob &quot;!*.lock&quot;
--colors &quot;line:fg:blue&quot;     # 行号着色为蓝色
--colors &quot;match:fg:yellow&quot;  # 命中内容着色为黄色
--colors &quot;path:fg:green&quot;    # 路径着色为绿色
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>注意：<code>--hidden</code> 全局开启后，搜索仓库时会连同 <code>.git</code> 一起扫，速度明显下降。<strong>不推荐</strong>常开，建议仅在 <code>rc</code> 里用 <code>--glob &quot;!.git/*&quot;</code> 兜底，或干脆不写 <code>--hidden</code>。</p></blockquote><p><strong>5. 关键环境变量</strong></p><table><thead><tr><th>环境变量</th><th>作用</th></tr></thead><tbody><tr><td><code>RIPGREP_CONFIG_PATH</code></td><td>指定自定义配置文件路径（默认 <code>~/.config/ripgrep/rc</code>）</td></tr><tr><td><code>RIPGREP_MAX_FILESIZE</code></td><td>跳过超过指定大小的文件，例如 <code>RIPGREP_MAX_FILESIZE=10M</code></td></tr><tr><td><code>RIPGREP_SUBMODULES</code></td><td>是否搜索 git 子模块（默认忽略）</td></tr></tbody></table><p>设置示例：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 全局跳过大于 10MB 的文件（在 ~/.zshrc 里写）</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable">RIPGREP_MAX_FILESIZE</span><span class="token operator">=</span>10M

<span class="token comment"># 用一份独立配置做敏感信息专项扫描</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable">RIPGREP_CONFIG_PATH</span><span class="token operator">=~</span>/cfg/rg-secrets-rc
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>6. 更多实用默认参数（适合写进 <code>rc</code>）</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>--max-columns 120     # 超长行只显示前 120 字符，防止刷屏
--heading            # 用标题分隔不同文件，多文件时更易读
--line-number        # 显示行号（本就默认，但显式写出更明确）
--sort path          # 输出按路径排序（默认按文件系统顺序）
--files-with-matches # 默认只列文件名（若你多数场景只看命中文件）
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>7. 自定文件类型（<code>--type-add</code>）</strong></p><p>对于 ripgrep 不认识的扩展名，可以用 <code>--type-add</code> 临时定义，或配合 <code>rc</code> 长期生效：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 把 .vue 与 .svelte 归入 &quot;html&quot; 类型，便于 -thtml</span>
rg --type-add <span class="token string">&#39;html:*.vue,*.svelte&#39;</span> <span class="token parameter variable">--type</span> html <span class="token string">&quot;onMounted&quot;</span> <span class="token builtin class-name">.</span>

<span class="token comment"># 自定义一种类型，并立即用它过滤</span>
rg --type-add <span class="token string">&#39;frontend:*.ts,*.tsx,*.jsx&#39;</span> <span class="token parameter variable">--type</span> frontend <span class="token string">&quot;className&quot;</span> src/
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_8-深入-多文件类型的精确控制" tabindex="-1"><a class="header-anchor" href="#_8-深入-多文件类型的精确控制" aria-hidden="true">#</a> 8. 深入：多文件类型的精确控制</h3><p>ripgrep 的 <code>-t/--type</code> 已内置数十种常见类型（<code>rust</code>、<code>py</code>、<code>js</code>、<code>go</code>、<code>ts</code>、<code>json</code>、<code>md</code>、<code>html</code>、<code>css</code>、<code>c</code>、<code>cpp</code> 等），但真实项目常有多后缀、模板引擎、冷门框架，需要更精细的控制：</p><p><strong>① 用 <code>-t</code> 组合多类型（<code>,</code> 分隔）</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 只搜 JS 和 TS 文件</span>
rg <span class="token string">&quot;useEffect&quot;</span> <span class="token parameter variable">-t</span> js,ts

<span class="token comment"># 查所有前端源码（js+ts+jsx+tsx+vue+svelte）——先归组再搜</span>
rg --type-add <span class="token string">&#39;web:*.{js,jsx,ts,tsx,vue,svelte}&#39;</span> <span class="token parameter variable">-t</span> web <span class="token string">&quot;api.get&quot;</span> <span class="token builtin class-name">.</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>② 用 <code>--type-add</code> 把扩展名并入已有类型，写入 <code>rc</code> 长期生效</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code># ~/.config/ripgrep/rc
--type-add &#39;js:*.mjs,*.cjs&#39;      # 现代 JS 模块后缀并入 js 类型
--type-add &#39;md:*.mdx&#39;            # MDX 并入 markdown
--type-add &#39;py:*.pyi&#39;            # 类型存根并入 python
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>写进 <code>rc</code> 后，所有 <code>-t js</code> / <code>-t md</code> 调用自动带上这些扩展名，团队项目多后缀/模板文件的搜索需求被统一满足。</p><p><strong>③ 查看某个类型包含哪些扩展名</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 列出内置全部类型及其扩展名（确认 -t 具体涵盖哪些文件）</span>
rg --type-list <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-E</span> <span class="token string">&#39;^(js|ts|html|md)&#39;</span>

<span class="token comment"># 只列文件（不搜内容），配合 -t 限定类型范围</span>
rg <span class="token parameter variable">--files</span> <span class="token parameter variable">-t</span> rs
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>④ 用 glob 做类型之外的精补</strong></p><p>当扩展名无法覆盖（例如按目录、按文件名模式过滤）时，glob 是 <code>-t</code> 的有力补充：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 只搜 test 目录下、排除 .snap 快照的 .js 文件</span>
rg <span class="token string">&quot;describe(&quot;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;test/**/*.js&#39;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;!*.snap&#39;</span>

<span class="token comment"># 只搜根目录层级的文件（不深入子目录）</span>
rg <span class="token string">&quot;config&quot;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;*.{json,yaml,yml}&#39;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;!**/node_modules/**&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>⑤ 用 <code>--iglob</code> 做大小写不敏感的 glob</strong></p><p>glob 默认大小写敏感，<code>--iglob</code> 则忽略大小写，适合跨平台/多命名风格项目：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>rg <span class="token string">&quot;token&quot;</span> <span class="token parameter variable">--iglob</span> <span class="token string">&#39;*.{ENV,env,Env}&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="_9-深入-速度优化-让-rg-快到极致" tabindex="-1"><a class="header-anchor" href="#_9-深入-速度优化-让-rg-快到极致" aria-hidden="true">#</a> 9. 深入：速度优化（让 rg 快到极致）</h3><p>rg 已很快，但针对巨型仓库/海量文件还能再榨性能：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># ① 用 -m 限制每个文件最多匹配 N 处，命中即停（大量&quot;找存在&quot;场景极快）</span>
rg <span class="token parameter variable">-m</span> <span class="token number">1</span> <span class="token string">&quot;TODO&quot;</span> <span class="token parameter variable">-t</span> rs

<span class="token comment"># ② 只搜内容中的指定列/字段：用正则锚定行首</span>
rg <span class="token string">&#39;^import&#39;</span> <span class="token parameter variable">-t</span> go                    <span class="token comment"># 只搜每行开头</span>
rg <span class="token string">&#39;\\b(v2|v3)\\b&#39;</span> <span class="token parameter variable">--json</span> <span class="token operator">|</span> jq <span class="token parameter variable">-r</span> <span class="token string">&#39;.data.path.text&#39;</span>

<span class="token comment"># ③ 跳过大文件（避免扫进 GB 级日志/二进制）</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable">RIPGREP_MAX_FILESIZE</span><span class="token operator">=</span>5M        <span class="token comment"># 或每次 --max-filesize 5M</span>

<span class="token comment"># ④ 用 --threads 显式控制并行线程数</span>
rg <span class="token string">&quot;pattern&quot;</span> <span class="token parameter variable">--threads</span> <span class="token number">8</span>              <span class="token comment"># 默认取 CPU 核数，可用 --threads 1 降噪对比</span>

<span class="token comment"># ⑤ 跳过耗时目录（编译产物、虚拟环境、.git）</span>
rg <span class="token string">&quot;foo&quot;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;!build/**&#39;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;!venv/**&#39;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;!target/**&#39;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;!.git/**&#39;</span>

<span class="token comment"># ⑥ 用 --stats 看瓶颈（扫了多少文件/多少字节/耗时）</span>
rg <span class="token string">&quot;foo&quot;</span> <span class="token parameter variable">-t</span> rs <span class="token parameter variable">--stats</span>
<span class="token comment"># 输出示例：</span>
<span class="token comment">#   1 matches</span>
<span class="token comment">#   34 matched lines</span>
<span class="token comment">#   2 files contained matches</span>
<span class="token comment">#   402 files searched</span>
<span class="token comment">#   209164 bytes searched</span>
<span class="token comment">#   0.148834 seconds</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>速度优化的核心思路</strong>：让 rg 扫描的<strong>文件更少</strong>（用 <code>-t</code>/<code>-g</code> 收窄）、<strong>单文件更快</strong>（<code>-m</code> 提前退出）、<strong>避开超大/二进制文件</strong>（<code>--max-filesize</code>），三条路任意一条都比无脑 <code>-uu</code> 全扫快一个数量级。</p><h3 id="_10-深入-输出格式化的进阶控制" tabindex="-1"><a class="header-anchor" href="#_10-深入-输出格式化的进阶控制" aria-hidden="true">#</a> 10. 深入：输出格式化的进阶控制</h3><p>ripgrep 的输出格式化能力远超&quot;打一行匹配&quot;，掌握这些能对接脚本、日志、diff：</p><p><strong>① 颜色控制（<code>--colors</code>）</strong></p><p><code>--colors</code> 的完整语法是 <code>&lt;哪一部分&gt;:&lt;颜色属性&gt;:&lt;值&gt;</code>，<code>&lt;哪一部分&gt;</code> 可选 <code>path</code>/<code>line</code>/<code>column</code>/<code>match</code>/<code>match_context</code>，<code>&lt;颜色属性&gt;</code> 可选 <code>fg</code>/<code>bg</code>/<code>style</code>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 命中文字加粗红底，路径青蓝，行号紫色</span>
rg <span class="token string">&quot;error&quot;</span> <span class="token parameter variable">--colors</span> <span class="token string">&#39;match:fg:red&#39;</span> <span class="token punctuation">\\</span>
           <span class="token parameter variable">--colors</span> <span class="token string">&#39;match:style:bold&#39;</span> <span class="token punctuation">\\</span>
           <span class="token parameter variable">--colors</span> <span class="token string">&#39;path:fg:cyan&#39;</span> <span class="token punctuation">\\</span>
           <span class="token parameter variable">--colors</span> <span class="token string">&#39;line:fg:magenta&#39;</span>

<span class="token comment"># 关闭某部分颜色</span>
rg <span class="token string">&quot;foo&quot;</span> <span class="token parameter variable">--colors</span> <span class="token string">&#39;match:none&#39;</span>

<span class="token comment"># 只看 256 色序号：fg:1 到 fg:255</span>
rg <span class="token string">&quot;foo&quot;</span> <span class="token parameter variable">--colors</span> <span class="token string">&#39;match:fg:196&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>② 列号与列定位（<code>--column</code>）</strong></p><p>默认输出 <code>文件:行号:内容</code>，加 <code>--column</code> 得到 <code>文件:行号:列号:内容</code>，可直接喂给编辑器 <code>vim file:line:col</code>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>rg <span class="token parameter variable">--column</span> <span class="token string">&quot;foo&quot;</span> <span class="token parameter variable">-t</span> rs <span class="token operator">|</span> <span class="token function">head</span> <span class="token parameter variable">-3</span>
<span class="token comment"># 输出：src/main.rs:12:5:    let foo = 1;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>③ 空分隔符模式（<code>-0</code>）配合 xargs</strong></p><p>文件名可能含空格/换行时，用 <code>-0</code>（NUL 分隔）与 <code>xargs -0</code> 配对，最安全：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>rg <span class="token parameter variable">-l</span> <span class="token parameter variable">-0</span> <span class="token string">&quot;TODO&quot;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;*.ts&#39;</span> <span class="token operator">|</span> <span class="token function">xargs</span> <span class="token parameter variable">-0</span> code
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><strong>④ 上下文分隔（<code>--context-separator</code>）</strong></p><p><code>-A/-B/-C</code> 输出多文件上下文时，用 <code>--context-separator</code> 自定义块分隔线：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>rg <span class="token parameter variable">-C</span> <span class="token number">2</span> <span class="token string">&quot;func&quot;</span> --context-separator <span class="token string">&#39;-----&#39;</span> <span class="token parameter variable">-t</span> go
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><strong>⑤ 用 <code>-o</code> + <code>--replace</code> 做&quot;提取&quot;型任务</strong></p><p><code>-o</code> 只输出命中片段，配合 <code>--replace</code> 改写，适合抽取/清洗文本：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 抽取所有链接地址</span>
rg <span class="token parameter variable">-o</span> <span class="token string">&#39;href=&quot;[^&quot;]+&quot;&#39;</span> index.html

<span class="token comment"># 把命中片段包上引号或标签</span>
rg <span class="token parameter variable">-o</span> <span class="token parameter variable">--replace</span> <span class="token string">&#39;&lt;$0&gt;&#39;</span> <span class="token string">&#39;https?://[^ ]+&#39;</span> readme.md

<span class="token comment"># 统计某类单词出现次数</span>
rg <span class="token parameter variable">-o</span> <span class="token string">&#39;\\b[a-z]+\\b&#39;</span> file.txt <span class="token operator">|</span> <span class="token function">sort</span> <span class="token operator">|</span> <span class="token function">uniq</span> <span class="token parameter variable">-c</span> <span class="token operator">|</span> <span class="token function">sort</span> <span class="token parameter variable">-rn</span> <span class="token operator">|</span> <span class="token function">head</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>⑥ JSON 结构化输出（<code>--json</code>）</strong></p><p><code>--json</code> 每行输出一个 JSON 对象，含 <code>type</code>（<code>begin</code>/<code>match</code>/<code>end</code> 等）、<code>path</code>、<code>lines</code>、<code>line_number</code>、<code>submatches</code> 等字段。脚本/CI 精确解析应走 JSON，别解析彩色文本：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 交给 jq 过滤出命中路径与行号</span>
rg <span class="token parameter variable">--json</span> <span class="token string">&quot;error&quot;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;*.go&#39;</span> <span class="token operator">|</span> jq <span class="token parameter variable">-r</span> <span class="token string">&#39;select(.type==&quot;match&quot;) | [.data.path.text,.data.line_number] | @tsv&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_11-深入-与-sed-fd-awk-的搭配实战" tabindex="-1"><a class="header-anchor" href="#_11-深入-与-sed-fd-awk-的搭配实战" aria-hidden="true">#</a> 11. 深入：与 sed / fd / awk 的搭配实战</h3><p><strong>① rg 定位 + sed 替换（批量重构最常用）</strong></p><p>先 dry-run、再替换、后清理备份，全程三件套，避免误改：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 第一步：确认命中的文件与行</span>
rg <span class="token parameter variable">-l</span> <span class="token string">&quot;old_api(&quot;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;*.py&#39;</span>

<span class="token comment"># 第二步：dry-run，打印将被替换的内容</span>
<span class="token function">sed</span> <span class="token parameter variable">-n</span> <span class="token string">&#39;s/old_api(/new_api(/gp&#39;</span> <span class="token punctuation">$(</span>rg <span class="token parameter variable">-l</span> <span class="token string">&quot;old_api(&quot;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;*.py&#39;</span><span class="token punctuation">)</span>

<span class="token comment"># 第三步：确认无误后再真正写回（-i 原地替换，macOS 需显式备份后缀）</span>
rg <span class="token parameter variable">-l</span> <span class="token string">&quot;old_api(&quot;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;*.py&#39;</span> <span class="token operator">|</span> <span class="token function">xargs</span> <span class="token function">sed</span> <span class="token parameter variable">-i.bak</span> <span class="token string">&#39;s/old_api(/new_api(/g&#39;</span>

<span class="token comment"># 清理备份文件</span>
rg <span class="token parameter variable">-l</span> <span class="token string">&quot;old_api(&quot;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;*.py&#39;</span> <span class="token operator">|</span> <span class="token function">xargs</span> -I<span class="token punctuation">{</span><span class="token punctuation">}</span> <span class="token function">rm</span> <span class="token parameter variable">-f</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>.bak
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>注意 macOS 自带 BSD sed 的 <code>-i</code> 必须带后缀（<code>-i.bak</code>），与 GNU sed 的 <code>-i</code> 行为不同。若脚本要跨平台，可用 <code>perl -pi -e</code> 替代，或装 GNU 版 <code>gsed</code>。</p></blockquote><p><strong>② fd 按文件名定位 + rg 按内容定位，组合成&quot;精确地图&quot;</strong></p><p><code>fd</code>（Rust 的 find 替代）专司&quot;按文件名/元数据找文件&quot;，rg 专司&quot;按内容找行&quot;，两者配合可把搜索范围收到极精准：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 只在 2024 年的日志文件里搜 &quot;ERROR&quot;</span>
fd <span class="token string">&#39;2024.*\\.log$&#39;</span> logs/ <span class="token operator">|</span> <span class="token function">xargs</span> rg <span class="token parameter variable">-n</span> <span class="token string">&quot;ERROR&quot;</span>

<span class="token comment"># 只搜 src 下超过 10KB 的 .rs 文件里的 &quot;unsafe&quot;</span>
fd <span class="token parameter variable">-e</span> rs <span class="token parameter variable">-s</span> <span class="token string">&#39;10k&#39;</span> src/ <span class="token operator">|</span> <span class="token function">xargs</span> rg <span class="token parameter variable">-n</span> <span class="token string">&quot;unsafe&quot;</span>

<span class="token comment"># 只搜最近 7 天改动过的 .ts 文件（fd 无时间过滤时用 find 兜底）</span>
<span class="token function">find</span> src <span class="token parameter variable">-name</span> <span class="token string">&#39;*.ts&#39;</span> <span class="token parameter variable">-mtime</span> <span class="token parameter variable">-7</span> <span class="token operator">|</span> <span class="token function">xargs</span> rg <span class="token parameter variable">-n</span> <span class="token string">&quot;TODO&quot;</span>

<span class="token comment"># 按文件类型找再按内容搜（fd 的 -e 类型过滤 + rg 的 -t）</span>
fd <span class="token parameter variable">-e</span> json <span class="token operator">|</span> <span class="token function">xargs</span> rg <span class="token string">&#39;&quot;host&quot;&#39;</span> <span class="token operator">|</span> <span class="token function">head</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>③ rg 输出 + awk 做后处理统计</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 统计每个文件匹配行数并排序</span>
rg <span class="token parameter variable">-c</span> <span class="token string">&quot;TODO&quot;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;*.ts&#39;</span> <span class="token operator">|</span> <span class="token function">awk</span> -F: <span class="token string">&#39;{print $2, $1}&#39;</span> <span class="token operator">|</span> <span class="token function">sort</span> <span class="token parameter variable">-rn</span> <span class="token operator">|</span> <span class="token function">head</span>

<span class="token comment"># 提取并统计某类 token 的 Top N</span>
rg <span class="token parameter variable">-o</span> <span class="token string">&#39;\\b(var|let|const)\\b&#39;</span> <span class="token parameter variable">-t</span> js <span class="token operator">|</span> <span class="token function">sort</span> <span class="token operator">|</span> <span class="token function">uniq</span> <span class="token parameter variable">-c</span> <span class="token operator">|</span> <span class="token function">sort</span> <span class="token parameter variable">-rn</span>

<span class="token comment"># 按模块聚合匹配数</span>
rg <span class="token parameter variable">-c</span> <span class="token string">&quot;legacy_api&quot;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;*.py&#39;</span> <span class="token operator">|</span> <span class="token function">awk</span> -F: <span class="token string">&#39;{print $2, $1}&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="六、注意事项与常见问题" tabindex="-1"><a class="header-anchor" href="#六、注意事项与常见问题" aria-hidden="true">#</a> 六、注意事项与常见问题</h2><p><strong>1. 默认忽略隐藏文件与 .gitignore 内容</strong></p><p>新手常惊讶为什么搜不到 <code>node_modules</code> 或 <code>.env</code> 里的内容——这是 ripgrep 的<strong>默认行为</strong>。需要时显式加 <code>-uu</code>（全部扫描）或 <code>--hidden</code>（仅包含隐藏文件）。</p><p><strong>2. 正则语法是 Rust 风格（非 PCRE）</strong></p><p>ripgrep 默认不支持 <code>\\d</code> 等 PCRE 语法，会报错或按字面匹配。要完整回溯引用需加 <code>-P</code> / <code>--pcre2</code> 启用 PCRE2：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>rg <span class="token parameter variable">-P</span> <span class="token string">&quot;(?&lt;year&gt;\\d{4})-<span class="token entity" title="\\1">\\1</span>&quot;</span> file.txt
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>常见&quot;报错但不知道为什么&quot;的写法：</p><ul><li><code>\\d</code>、<code>\\w</code>、<code>\\b</code> 直接写会报 <strong>unrecognized escape sequence</strong>——这些属于 PCRE 语法，需 <code>-P</code>，或用 Rust 风格 <code>[0-9]</code>、<code>[[:word:]]</code>、<code>(?&lt;![[:word:]])</code> 等。</li><li>使用 <code>(a|b)</code> 是<strong>捕获组</strong>，需要<strong>非捕获组</strong>时写 <code>(?:a|b)</code>，别把 <code>?P&lt;name&gt;</code>（PCRE 命名组）直接套用，除非加 <code>-P</code>。</li><li>若正则里含 <code>{</code>、<code>}</code> 等字符而报错，先确认是否被 shell 展开，必要时用单引号包裹 pattern。</li></ul><p><strong>3. 输出默认带行号且按路径排序</strong></p><p>与 grep 行为不同，<code>rg</code> 默认打印行号。若脚本里需要纯文本输出，用 <code>-N</code> / <code>--no-line-number</code>。</p><p><strong>4. 大文件与二进制文件</strong></p><p>搜索超大文件（GB 级）时 ripgrep 速度仍快，但内存占用会上升。二进制文件默认被跳过并提示 &quot;binary file matches&quot;，如需处理二进制内容用 <code>-a</code> / <code>--text</code> 强制按文本处理，谨慎使用以免乱码。</p><p><strong>5. 中文内容搜索</strong></p><p>直接 <code>rg &quot;关键字&quot;</code> 即可搜索 UTF-8 中文，无需额外参数。但若文件是 GBK 等非 UTF-8 编码，可能需要先转码或用 <code>--encoding gbk</code> 指定编码：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>rg <span class="token parameter variable">--encoding</span> gbk <span class="token string">&quot;中文&quot;</span> oldfile.txt
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><strong>6. 与系统 grep 的差异</strong></p><p><code>rg</code> 不是 grep 的直接替代品：它更专注代码搜索，缺少数 grep 的流式处理与 POSIX 兼容性。在管道处理文本流（如 <code>ps aux | rg xx</code>）时也完全可用，但涉及 <code>grep -E</code> 等严格 POSIX 行为时需注意参数差异。</p><h3 id="进阶排查-为什么-搜不到" tabindex="-1"><a class="header-anchor" href="#进阶排查-为什么-搜不到" aria-hidden="true">#</a> 进阶排查：为什么&quot;搜不到&quot;</h3><table><thead><tr><th>现象</th><th>最可能原因</th><th>排查与解决</th></tr></thead><tbody><tr><td>明明文件里有该字符串却搜不到</td><td>文件被 <code>.gitignore</code> / <code>.ignore</code> 忽略，或是隐藏文件</td><td>先 <code>rg -l pattern --hidden</code>，再不行 <code>rg -uu</code>；检查 <code>rg --files</code> 是否能列出该文件</td></tr><tr><td>报 <code>unrecognized escape sequence</code></td><td>用了 PCRE 语法 <code>\\d</code> 等</td><td>加 <code>-P</code>，或改用 Rust 风格字符类</td></tr><tr><td>报 <code>unrecognized flag</code></td><td>某个参数拼写/缩写错误，或参数顺序有问题</td><td><code>rg --help</code> 查准确拼写；选项应写在 pattern 之前</td></tr><tr><td>结果乱码/空</td><td>文件是 GBK 等非 UTF-8 编码</td><td>加 <code>--encoding gbk</code> 显式指定编码</td></tr><tr><td>超大仓库扫得太慢</td><td>没限定文件范围，扫了构建产物</td><td>用 <code>-t</code>/<code>-g</code> 缩小范围；确认没在 <code>rc</code> 里误开 <code>--hidden</code>；用 <code>--stats</code> 看扫了多少文件</td></tr><tr><td><code>binary file matches</code> 反复出现</td><td>撞上含二进制字节的文本/日志</td><td>若确需全文搜索，加 <code>-a</code>；否则可忽略该提示</td></tr><tr><td>内存被占满/OOM</td><td>搜索了巨型或未压缩的二进制大文件</td><td>设 <code>RIPGREP_MAX_FILESIZE=10M</code>；改用 <code>-g &#39;!*.log&#39;</code> 等排除</td></tr><tr><td><code>-t js</code> 搜不到 <code>.mjs</code> 文件</td><td>类型映射未覆盖新后缀</td><td><code>--type-add &#39;js:*.mjs&#39;</code> 或加 glob</td></tr><tr><td>路径里含空格导致 xargs 报错</td><td>xargs 默认按空格分词</td><td>用 <code>rg -0</code> + <code>xargs -0</code> 配对</td></tr><tr><td>文件名中文乱码</td><td>终端/文件编码非 UTF-8</td><td>确认 <code>$LANG</code> 为 UTF-8；用 <code>--encoding</code> 指定源编码</td></tr></tbody></table><p><strong>7. 性能与安全注意点</strong></p><ul><li><strong>不要把 <code>-uu</code> 当默认</strong>：它无视所有忽略规则，会让扫描量暴增，也可能扫入 <code>.git</code>、密钥目录等不该看的内容。只在有明确需求时对<strong>指定目录</strong>使用。</li><li><strong>搜&quot;根目录全盘&quot;要克制</strong>：<code>rg xxx /</code> 会扫遍整个磁盘，极慢且无必要。先 <code>cd</code> 到目标子目录再搜。</li><li><strong>注意 <code>-P</code>（PCRE2）的性能</strong>：<code>-P</code> 启用后性能显著低于默认引擎。能不用回溯就尽量用默认正则；确认必须用时再开。</li><li><strong>敏感信息扫描要带范围</strong>：排查密钥、Token 时，先想清楚要扫哪些目录，用 <code>-g</code> 收窄，避免误报与泄露面扩大。</li><li><strong>小心 shell 特殊字符</strong>：<code>!</code>、<code>$</code>、<code>*</code>、<code>(</code> 等在未加引号时会被 shell 解释。pattern 一律加单引号可避开大部分坑。</li><li><strong>批量替换前务必 dry-run + 备份</strong>：<code>rg</code> 只负责定位，写回用 <code>sed -i</code>；正式操作前先在 <code>sed -n &#39;s/.../.../gp&#39;</code> 演练，并保留 <code>.bak</code> 备份，防手滑误改。</li><li><strong>大仓库别开 <code>--heading</code> 后管道给脚本</strong>：heading 输出含控制字符，脚本解析请用 <code>--json</code> 或 <code>-N</code> 纯文本。</li></ul><h2 id="七、实战-与其它工具搭配与自动化" tabindex="-1"><a class="header-anchor" href="#七、实战-与其它工具搭配与自动化" aria-hidden="true">#</a> 七、实战：与其它工具搭配与自动化</h2><h3 id="_1-与-fd-搭配-先找文件-再搜内容" tabindex="-1"><a class="header-anchor" href="#_1-与-fd-搭配-先找文件-再搜内容" aria-hidden="true">#</a> 1. 与 fd 搭配（&quot;先找文件，再搜内容&quot;）</h3><p><code>fd</code> 是同类 Rust 工具，专司&quot;按文件名找&quot;。两者组合可精确控制&quot;在哪一类文件里搜&quot;：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 只在 2024 年的日志文件里搜 &quot;ERROR&quot;</span>
fd <span class="token string">&#39;2024.*\\.log$&#39;</span> logs/ <span class="token operator">|</span> <span class="token function">xargs</span> rg <span class="token parameter variable">-n</span> <span class="token string">&quot;ERROR&quot;</span>

<span class="token comment"># 只搜 src 下超过 10KB 的 .rs 文件里的 &quot;unsafe&quot;</span>
fd <span class="token parameter variable">-e</span> rs <span class="token parameter variable">-s</span> <span class="token string">&#39;10k&#39;</span> src/ <span class="token operator">|</span> <span class="token function">xargs</span> rg <span class="token parameter variable">-n</span> <span class="token string">&quot;unsafe&quot;</span>

<span class="token comment"># 只搜最近 7 天改动过的 .ts 文件（fd 无时间过滤时用 find 兜底）</span>
<span class="token function">find</span> src <span class="token parameter variable">-name</span> <span class="token string">&#39;*.ts&#39;</span> <span class="token parameter variable">-mtime</span> <span class="token parameter variable">-7</span> <span class="token operator">|</span> <span class="token function">xargs</span> rg <span class="token parameter variable">-n</span> <span class="token string">&quot;TODO&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-与-sed-搭配-先定位-再精确替换" tabindex="-1"><a class="header-anchor" href="#_2-与-sed-搭配-先定位-再精确替换" aria-hidden="true">#</a> 2. 与 sed 搭配（先定位，再精确替换）</h3><p>rg 定位 + sed 批量替换是常见组合，但要<strong>先 dry-run 确认</strong>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 第一步：确认命中的文件与行</span>
rg <span class="token parameter variable">-l</span> <span class="token string">&quot;old_api(&quot;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;*.py&#39;</span>

<span class="token comment"># 第二步：dry-run，打印将被替换的内容</span>
<span class="token function">sed</span> <span class="token parameter variable">-n</span> <span class="token string">&#39;s/old_api(/new_api(/gp&#39;</span> <span class="token punctuation">$(</span>rg <span class="token parameter variable">-l</span> <span class="token string">&quot;old_api(&quot;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;*.py&#39;</span><span class="token punctuation">)</span>

<span class="token comment"># 第三步：确认无误后再真正写回（-i 原地替换，macOS 需显式备份后缀）</span>
rg <span class="token parameter variable">-l</span> <span class="token string">&quot;old_api(&quot;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;*.py&#39;</span> <span class="token operator">|</span> <span class="token function">xargs</span> <span class="token function">sed</span> <span class="token parameter variable">-i.bak</span> <span class="token string">&#39;s/old_api(/new_api(/g&#39;</span>

<span class="token comment"># 清理备份文件</span>
rg <span class="token parameter variable">-l</span> <span class="token string">&quot;old_api(&quot;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;*.py&#39;</span> <span class="token operator">|</span> <span class="token function">xargs</span> -I<span class="token punctuation">{</span><span class="token punctuation">}</span> <span class="token function">rm</span> <span class="token parameter variable">-f</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>.bak
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>注意 macOS 自带 BSD sed 的 <code>-i</code> 必须带后缀（<code>-i.bak</code>），与 GNU sed 的 <code>-i</code> 行为不同。若脚本要跨平台，可用 <code>perl -pi -e</code> 替代，或装 GNU 版 <code>gsed</code>。</p></blockquote><h3 id="_3-与-fzf-形成-搜索-→-选择-→-打开-流水线" tabindex="-1"><a class="header-anchor" href="#_3-与-fzf-形成-搜索-→-选择-→-打开-流水线" aria-hidden="true">#</a> 3. 与 fzf 形成&quot;搜索 → 选择 → 打开&quot;流水线</h3><p>把命中文件交给 fzf 交互选择，回车即打开：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 定义到 shell 里当函数用（写入 ~/.zshrc）</span>
<span class="token function-name function">rgopen</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token builtin class-name">local</span> f
  <span class="token assign-left variable">f</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span>rg <span class="token parameter variable">-l</span> <span class="token string">&quot;<span class="token variable">$1</span>&quot;</span> $<span class="token punctuation">{</span><span class="token number">2</span>:-.<span class="token punctuation">}</span> <span class="token operator">|</span> fzf <span class="token parameter variable">--preview</span> <span class="token string">&#39;rg -n &quot;$1&quot; {}&#39;</span><span class="token variable">)</span></span>
  <span class="token punctuation">[</span> <span class="token parameter variable">-n</span> <span class="token string">&quot;<span class="token variable">$f</span>&quot;</span> <span class="token punctuation">]</span> <span class="token operator">&amp;&amp;</span> <span class="token variable">$EDITOR</span> <span class="token string">&quot;<span class="token variable">$f</span>&quot;</span>
<span class="token punctuation">}</span>
<span class="token comment"># 用法：rgopen &quot;handle_request&quot; src/</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>配合 <code>--preview</code> 还能实时预览命中上下文，无需打开文件即可判断是否要找的目标。</p><h3 id="_4-与-bat-搭配美化输出" tabindex="-1"><a class="header-anchor" href="#_4-与-bat-搭配美化输出" aria-hidden="true">#</a> 4. 与 bat 搭配美化输出</h3><p><code>bat</code> 是带语法高亮的 cat 替代品，<code>rg</code> 的 JSON 输出可配合解析，或直接流水到 bat：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 用 bat 的高亮阅读多文件命中结果（手动给文件名加分隔）</span>
rg <span class="token parameter variable">-n</span> <span class="token string">&quot;error&quot;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;*.rs&#39;</span> <span class="token operator">|</span> bat

<span class="token comment"># 若装了 delta（git 高亮 diff 工具），可做更花哨的输出</span>
<span class="token comment"># export RIPGREP_CONFIG_PATH=~/cfg/rg-bat-rc  # 里面写 --colors 等</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-写进-makefile-自动化" tabindex="-1"><a class="header-anchor" href="#_5-写进-makefile-自动化" aria-hidden="true">#</a> 5. 写进 Makefile 自动化</h3><p>把常用搜索固化为 target，团队一致化：</p><div class="language-makefile line-numbers-mode" data-ext="makefile"><pre class="language-makefile"><code><span class="token builtin-target builtin">.PHONY</span><span class="token punctuation">:</span> search search-todo check-secrets

<span class="token comment"># 用法：make search q=&quot;TODO&quot;</span>
<span class="token target symbol">search</span><span class="token punctuation">:</span>
	rg -n --heading <span class="token string">&quot;$(q)&quot;</span> .

<span class="token target symbol">search-todo</span><span class="token punctuation">:</span>
	rg -n <span class="token string">&quot;TODO|FIXME|HACK&quot;</span> --glob <span class="token string">&#39;!vendor/*&#39;</span> --glob <span class="token string">&#39;!node_modules/*&#39;</span> .

<span class="token target symbol">check-secrets</span><span class="token punctuation">:</span>
	rg -uu -l -e <span class="token string">&quot;BEGIN (RSA|OPENSSH|EC) PRIVATE KEY&quot;</span> -e <span class="token string">&quot;sk-[A-Za-z0-9]{20,}&quot;</span> . \\
		&amp;&amp; echo <span class="token string">&quot;!! 发现疑似密钥，请处理&quot;</span> &amp;&amp; exit 1 <span class="token operator">|</span><span class="token operator">|</span> echo <span class="token string">&quot;OK：未发现密钥&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 调用</span>
<span class="token function">make</span> search <span class="token assign-left variable">q</span><span class="token operator">=</span><span class="token string">&quot;fixme&quot;</span>
<span class="token function">make</span> check-secrets
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-ci-集成-作为静态检查门禁" tabindex="-1"><a class="header-anchor" href="#_6-ci-集成-作为静态检查门禁" aria-hidden="true">#</a> 6. CI 集成（作为静态检查门禁）</h3><p>在 GitHub Actions 等 CI 里，让 rg 作为&quot;门禁&quot;：搜到敏感信息就让构建失败。</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token comment"># .github/workflows/secret-scan.yml</span>
<span class="token key atrule">name</span><span class="token punctuation">:</span> Secret scan
<span class="token key atrule">on</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>push<span class="token punctuation">,</span> pull_request<span class="token punctuation">]</span>
<span class="token key atrule">jobs</span><span class="token punctuation">:</span>
  <span class="token key atrule">scan</span><span class="token punctuation">:</span>
    <span class="token key atrule">runs-on</span><span class="token punctuation">:</span> ubuntu<span class="token punctuation">-</span>latest
    <span class="token key atrule">steps</span><span class="token punctuation">:</span>
      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/checkout@v4
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Install ripgrep
        <span class="token key atrule">run</span><span class="token punctuation">:</span> sudo apt<span class="token punctuation">-</span>get install <span class="token punctuation">-</span>y ripgrep   <span class="token comment"># 或 cargo install ripgrep</span>
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Scan for leaked secrets
        <span class="token key atrule">run</span><span class="token punctuation">:</span> <span class="token punctuation">|</span><span class="token scalar string">
          if rg -uu -n -e &#39;BEGIN PRIVATE KEY&#39; \\
                     -e &#39;AKIA[0-9A-Z]{16}&#39; \\
                     -e &#39;sk-[A-Za-z0-9]{20,}&#39; \\
                     --glob &#39;!.git/*&#39; .; then
            echo &quot;::error::检测到疑似密钥泄露，请立即处理&quot;
            exit 1
          else
            echo &quot;::notice::未发现疑似密钥&quot;
          fi</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>CI 中也可复用 Makefile 的 <code>check-secrets</code> target：<code>make check-secrets</code>。</p></blockquote><h3 id="_7-批量统计与巡检" tabindex="-1"><a class="header-anchor" href="#_7-批量统计与巡检" aria-hidden="true">#</a> 7. 批量统计与巡检</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 统计各模块 TODO 数量，辅助排期</span>
<span class="token keyword">for</span> <span class="token for-or-select variable">d</span> <span class="token keyword">in</span> src/services src/controllers src/models<span class="token punctuation">;</span> <span class="token keyword">do</span>
  <span class="token builtin class-name">printf</span> <span class="token string">&quot;%-20s %s<span class="token entity" title="\\n">\\n</span>&quot;</span> <span class="token string">&quot;<span class="token variable">$d</span>&quot;</span> <span class="token string">&quot;<span class="token variable"><span class="token variable">$(</span>rg <span class="token parameter variable">-c</span> <span class="token string">&#39;TODO&#39;</span> $d <span class="token parameter variable">-g</span> <span class="token string">&#39;*.ts&#39;</span> <span class="token operator">|</span> <span class="token function">awk</span> -F: <span class="token string">&#39;{s+=$2} END{print s+0}&#39;</span><span class="token variable">)</span></span>&quot;</span>
<span class="token keyword">done</span>

<span class="token comment"># 找出重复的 import（同文件出现两次同名模块，示意）</span>
rg <span class="token parameter variable">-o</span> <span class="token string">&#39;^import\\s+[A-Za-z0-9_]+&#39;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;*.go&#39;</span> <span class="token operator">|</span> <span class="token function">sort</span> <span class="token operator">|</span> <span class="token function">uniq</span> <span class="token parameter variable">-d</span>

<span class="token comment"># 列出引用某即将废弃 API 的所有文件，供迁移</span>
rg <span class="token parameter variable">-l</span> <span class="token string">&quot;LegacyClient\\(&quot;</span> <span class="token parameter variable">-t</span> js,ts <span class="token operator">|</span> <span class="token function">sort</span> <span class="token operator">&gt;</span> legacy_users.txt
<span class="token function">wc</span> <span class="token parameter variable">-l</span> legacy_users.txt
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_8-用-rg-做代码规范-未使用依赖门禁" tabindex="-1"><a class="header-anchor" href="#_8-用-rg-做代码规范-未使用依赖门禁" aria-hidden="true">#</a> 8. 用 rg 做代码规范/未使用依赖门禁</h3><p>把 rg 接入 lint 流程，可拦截&quot;引用了但未声明的符号&quot;等低级问题（示意）：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 检查是否有直接拼错/漏配的引用（配合类型系统可减少误报）</span>
rg <span class="token parameter variable">-n</span> <span class="token string">&quot;from [&#39;<span class="token entity" title="\\&quot;">\\&quot;</span>]\\.\\./v1&quot;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;*.ts&#39;</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-v</span> <span class="token string">&#39;v1/index&#39;</span> <span class="token operator">||</span> <span class="token builtin class-name">echo</span> <span class="token string">&quot;无残留 v1 引用&quot;</span>

<span class="token comment"># 检查硬编码密钥（简单版，CI 可挂）</span>
rg <span class="token parameter variable">-n</span> <span class="token string">&quot;(password|api_key|token)\\s*=\\s*[&#39;<span class="token entity" title="\\&quot;">\\&quot;</span>][^&#39;<span class="token entity" title="\\&quot;">\\&quot;</span>]+[&#39;<span class="token entity" title="\\&quot;">\\&quot;</span>]&quot;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;!*.test.*&#39;</span> <span class="token parameter variable">-g</span> <span class="token string">&#39;!*.md&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_9-生产级实践建议" tabindex="-1"><a class="header-anchor" href="#_9-生产级实践建议" aria-hidden="true">#</a> 9. 生产级实践建议</h3><ul><li><strong>配置单一化</strong>：把常用参数收敛进 <code>~/.config/ripgrep/rc</code>，团队可把该文件纳入 dotfiles 仓库版本管理，跨机一致。</li><li><strong>用 <code>--json</code> 对接脚本</strong>：需要精确解析（行号、列号、上下文、匹配片段）时走 JSON，比解析彩色文本稳得多。</li><li><strong>给&quot;危险操作&quot;设保护</strong>：用别名或脚本包裹替换类命令，强制先 dry-run、自动备份，避免误删/误改。</li><li><strong>配合 CI 固定版本</strong>：锁定 ripgrep 版本号（如 <code>brew list --versions ripgrep</code>），CI 用固定版本，保证行为一致。</li><li><strong>善用 <code>--stats</code> 建立基线</strong>：定期跑 <code>rg --stats</code> 记录扫描文件数/耗时，异常增长说明忽略了规则被误改或仓库膨胀，可及早发现。</li><li><strong>把&quot;类型 + glob + 大文件上限&quot;写进 <code>rc</code></strong>：团队统一后，人人搜索都又快又准，还能避免误扫构建产物。</li><li><strong>给替换类操作加&quot;保护别名&quot;</strong>：例如用 <code>alias rg-sed-safe</code> 包裹&quot;先 dry-run + 自动备份&quot;的完整流程，杜绝裸 <code>sed -i</code> 事故。</li></ul>`,148),r=[o];function c(i,l){return a(),n("div",null,r)}const u=s(t,[["render",c],["__file","ripgrep.html.vue"]]);export{u as default};
